package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "nil on zero width",
			text:  "hello world",
			width: 0,
			want:  nil,
		},
		{
			name:  "nil on negative width",
			text:  "hello world",
			width: -5,
			want:  nil,
		},
		{
			name:  "empty string",
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			name:  "whitespace only",
			text:  "   ",
			width: 10,
			want:  nil,
		},
		{
			name:  "single word fits",
			text:  "hello",
			width: 10,
			want:   []string{"hello"},
		},
		{
			name:  "two words fit",
			text:  "hello world",
			width: 15,
			want:   []string{"hello world"},
		},
		{
			name:  "wrap at space",
			text:  "hello world foo",
			width: 12,
			want:   []string{"hello world", "foo"},
		},
		{
			name:  "long word exceeds width",
			text:  "superlongword short",
			width: 10,
			want:   []string{"superlongword", "short"},
		},
		{
			name:  "word longer than width alone",
			text:  "impossibleword",
			width: 5,
			want:   []string{"impossibleword"},
		},
		{
			name:  "collapse multiple spaces",
			text:  "a   b    c",
			width: 10,
			want:   []string{"a b c"},
		},
		{
			name:  "no trailing or leading spaces",
			text: "  hello   world  ",
			width: 10,
			want:   []string{"hello", "world"},
		},
		{
			name:  "multiple wraps",
			text:  "one two three four five six seven eight nine ten",
			width: 15,
			want:   []string{"one two", "three four", "five six", "seven eight", "nine ten"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == 0 && got == nil && len(tt.want) == 0 && tt.want == nil {
				return // both nil
			}
			if len(got) != len(tt.want) {
				t.Fatalf("got %d lines, want %d\nlines: %q\nwant: %q", len(got), len(tt.want), got, tt.want)
			}
			for i, w := range tt.want {
				if got[i] != w {
					t.Errorf("line %d: got %q, want %q", i, got[i], w)
				}
			}
		})
	}
}

